export function parseRange(text) {
  const [from, to] = text.split("-");
  const fromNum = Number(from);
  return { from: fromNum, to: to === undefined ? fromNum : Number(to) };
}

response.text:
The `parseRange` function was failing for single-number inputs (e.g., `"7"`) because it attempted to convert `undefined` to a number, resulting in `NaN`. I updated the function to handle cases where the range consists of a single value by setting the `to` property equal to the `from` property when no hyphen is present.

```javascript
export function parseRange(text) {
  const [from, to] = text.split("-");
  const fromNum = Number(from);
  return { from: fromNum, to: to === undefined ? fromNum : Number(to) };
}
```
